// Generated by /ship test coverage audit (pass 1).
// Value: protects=export file names are legal on every OS and never empty; the export-age reminder counts whole days; sidebar Now/Yesterday buckets;
//   fails_when=the illegal-character strip, the Untitled fallback or the 80-char cap is removed, or daysSince rounds up / mishandles null;
//   why_new=no test imports platform.ts; e2e only checks one plain title ('Export me.md'); seam=none;
//   no_claim=locale-specific time/weekday/date strings from when() (only the locale-free buckets are asserted)
import { describe, expect, it } from 'vitest';
import { daysSince, safeFileName, when } from './platform';

const DAY = 86_400_000;

describe('safeFileName', () => {
  it('strips characters that are illegal in file names on Windows/macOS', () => {
    expect(safeFileName('Notes: a/b\\c *draft*? "<x>|"')).toBe('Notes abc draft x');
  });
  it('falls back to Untitled for empty or all-illegal titles', () => {
    expect(safeFileName('')).toBe('Untitled');
    expect(safeFileName('///:::')).toBe('Untitled');
    expect(safeFileName('   ')).toBe('Untitled');
  });
  it('caps the name at 80 characters', () => {
    expect(safeFileName('x'.repeat(200))).toHaveLength(80);
  });
});

describe('daysSince (export reminder, R10)', () => {
  const now = Date.UTC(2026, 9, 23, 12);
  it('is null when never exported', () => expect(daysSince(null, now)).toBeNull());
  it('counts only whole days', () => {
    expect(daysSince(now - 7 * DAY + 1, now)).toBe(6);
    expect(daysSince(now - 7 * DAY, now)).toBe(7);
    expect(daysSince(now, now)).toBe(0);
  });
});

describe('when (sidebar)', () => {
  const midnight = new Date(2026, 9, 23).getTime(); // local midnight
  const now = midnight + 15 * 3_600_000;
  it('says Now within a minute and Yesterday for the previous local day', () => {
    expect(when(now - 30_000, now)).toBe('Now');
    expect(when(midnight - 1, now)).toBe('Yesterday');
    expect(when(midnight - DAY, now)).toBe('Yesterday');
    expect(when(midnight - DAY - 1, now)).not.toBe('Yesterday');
  });
});
